@CrossOrigin
@RestController
@RequestMapping("/TrainingCourseQuery")
public class TrainingCourseQueryRestController extends BaseSpringRestController {
	
	public TrainingCourseQueryRestController( TrainingCourseService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a TrainingCourse using a UUID
     * @param		UUID trainingCourseId
     * @return		TrainingCourse
     */    
    @GetMapping("/load")
    public TrainingCourse load( @RequestParam(required=true) UUID trainingCourseId ) {
    	TrainingCourse entity = null;

    	try {  
    		entity = service.getTrainingCourse( new TrainingCourseFetchOneSummary( trainingCourseId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load TrainingCourse using Id " + trainingCourseId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all TrainingCourse business objects
     * @return		Set<TrainingCourse>
     */
    @GetMapping("/")
    public List<TrainingCourse> loadAll() {                
    	List<TrainingCourse> trainingCourseList = null;
        
    	try {
            // load the TrainingCourse
            trainingCourseList = service.getAllTrainingCourse();
            
            if ( trainingCourseList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all TrainingCourses" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all TrainingCourses ", exc );
        	return null;
        }

        return trainingCourseList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected TrainingCourse trainingCourse = null;
    protected TrainingCourseService service = null;
    private static final Logger LOGGER = Logger.getLogger(TrainingCourseQueryRestController.class.getName());
    
}
